        sum1[i]=(sum1[i-1]+(r-l+1)%mo*(i-1))%mo;
        sum2[i]=(sum2[i-1]+Calc2(l,r)*(i-1))%mo;
        sum3[i]=(sum3[i-1]+Calc3(l,r)*(i-1))%mo;
    }
    for (LL i=0;i*i<=n;i++) {
        f[i]=getf(n-i*i);
        g[i]=getg(n-i*i);
        h[i]=geth(n-i*i);
    }
}
void work() {
    LL ans1=0;
    for (LL i=0;i*i<=n;i++) {
        LL nowx=i*i%mo*f[i]+g[i];
        nowx%=mo;
        ans1=(ans1+nowx)%mo;
    }
    ans1=ans1*4%mo;
    LL nowx=(nx+1)*nx%mo*inv2%mo;
    ans1=(ans1+nowx)%mo;
    ans1=ans1*(nx+1)%mo;
    LL ans2=0;
    for (LL i=0;i*i<=n;i++) {
        LL nowp=i*i%mo;
        LL nowx=nowp*nowp%mo*f[i]+nowp*2*g[i]+h[i];
        nowx%=mo;
        ans2=(ans2+nowx)%mo;
    }
    ans2=ans2*4%mo;
    nowx=getsum(nx);
    ans2=(ans2+nowx)%mo;
    ans1=((ans1-ans2)%mo+mo)%mo;
    printf("%lld\n",ans1);
}
int main() {
    scanf("%lld",&n);
    prework();
    work();
    return 0;
}
